const profileRequestCount = `-- name: ProfileRequestCount :one
SELECT COALESCE(SUM(count), 0)::bigint AS requests, COUNT(*)::bigint AS observations
FROM request_telemetry
WHERE account_id = $1::text::uuid AND app_id = $2::text::uuid
  AND deployment_id = $3::text::uuid
  AND ($4::text='' OR route=$4::text)
  AND received_at >= $5::timestamptz AND received_at < $6::timestamptz
`

type ProfileRequestCountParams struct {
	AccountID    string
	AppID        string
	DeploymentID string
	Route        string
	StartAt      pgtype.Timestamptz
	EndAt        pgtype.Timestamptz
}

type ProfileRequestCountRow struct {
	Requests     int64
	Observations int64
}

func (q *Queries) ProfileRequestCount(ctx context.Context, db DBTX, arg ProfileRequestCountParams) (ProfileRequestCountRow, error) {
	row := db.QueryRow(ctx, profileRequestCount,
		arg.AccountID,
		arg.AppID,
		arg.DeploymentID,
		arg.Route,
		arg.StartAt,
		arg.EndAt,
	)
	var i ProfileRequestCountRow
	err := row.Scan(&i.Requests, &i.Observations)
	return i, err
}

const profileRequestMix = `-- name: ProfileRequestMix :many
WITH filtered AS (
 SELECT t.route, t.method, t.status, t.count::bigint AS weight
 FROM request_telemetry t
 JOIN apps a ON a.id=t.app_id AND a.account_id=t.account_id AND a.status<>'deleted'
 JOIN deployments d ON d.id=t.deployment_id AND d.app_id=t.app_id
 WHERE t.account_id=$2::text::uuid AND t.app_id=$3::text::uuid
 AND t.deployment_id=$4::text::uuid
 AND ($5::text='' OR t.route=$5::text)
 AND t.received_at>=$6::timestamptz AND t.received_at<$7::timestamptz
), grouped AS (
 SELECT 'route'::text AS dimension, route::text AS label, method::text AS method, SUM(weight)::bigint AS requests
 FROM filtered GROUP BY route, method
 UNION ALL
 SELECT 'status'::text, ((status / 100)::text || 'xx')::text, ''::text, SUM(weight)::bigint
 FROM filtered GROUP BY status / 100
), ranked AS (
 SELECT dimension,label,method,requests,
 SUM(requests) OVER (PARTITION BY dimension)::bigint AS total,
 ROW_NUMBER() OVER (PARTITION BY dimension ORDER BY requests DESC,label,method) AS position
 FROM grouped
)
SELECT dimension,label,method,requests,total FROM ranked
WHERE dimension='status' OR position<=$1::int
ORDER BY dimension,requests DESC,label,method
`

type ProfileRequestMixParams struct {
	MaxRoutes    int32
	AccountID    string
	AppID        string
	DeploymentID string
	Route        string
	StartAt      pgtype.Timestamptz
	EndAt        pgtype.Timestamptz
}

type ProfileRequestMixRow struct {
	Dimension string
	Label     string
	Method    string
	Requests  int64
	Total     int64
}

func (q *Queries) ProfileRequestMix(ctx context.Context, db DBTX, arg ProfileRequestMixParams) ([]ProfileRequestMixRow, error) {
	rows, err := db.Query(ctx, profileRequestMix,
		arg.MaxRoutes,
		arg.AccountID,
		arg.AppID,
		arg.DeploymentID,
		arg.Route,
		arg.StartAt,
		arg.EndAt,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ProfileRequestMixRow{}
	for rows.Next() {
		var i ProfileRequestMixRow
		if err := rows.Scan(
			&i.Dimension,
			&i.Label,
			&i.Method,
			&i.Requests,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

